#include <memory>
#include <iterator>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::allocator<int> allocator;
    int *storage = allocator.allocate(2);
    std::raw_storage_iterator<int *, int> output{storage};
    assert(output.base() == storage);
    *output = 7;
    ++output;
    *output++ = 9;
    assert(storage[0] == 7 && storage[1] == 9);
    allocator.destroy(storage);
    allocator.destroy(storage + 1);
    allocator.deallocate(storage, 2);
}
